#!/usr/bin/env bash
#
# start-sites.sh - run one Bialet server per generated app, on consecutive
# ports, with logs under bench/work/logs and per-process RSS sampling under
# the results directory.
#
# Each app is bench/work/apps/site-N, generated by gen-sites.sh. Bialet runs a
# supervisor plus one HTTP child; the manifest records both pids because perf,
# heaptrack and strace attach to the child.
#
# Usage: start-sites.sh [options]
#   --count N          Number of apps/servers (default: 8)
#   --port-base N      First port; sites use base, base+1, ... (default: 8100)
#   --apps-dir DIR     Generated apps (default: bench/work/apps)
#   --binary PATH      Server binary (default: build/bialet)
#   --bind-host HOST   Listen address (default: 127.0.0.1)
#   --flags STRING     Extra server flags, e.g. "-x -w" (default: "-x -w")
#   --log-dir DIR      Log directory (default: bench/work/logs)
#   --manifest FILE    Manifest output (default: bench/work/run/sites.tsv)
#   --pids-file FILE   Child-pid file for mem.sh (default: bench/work/run/sites.pids)
#   --results DIR      RSS output directory (default: results/<UTC>/mem)
#   --no-rss           Do not start the RSS sampler
#   --hz N             RSS samples per second (default: 5)
#   --wait SEC         Seconds to wait for each port (default: 60)
#   -h, --help         Show this help

set -euo pipefail

# shellcheck source=lib/common.sh
source "$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)/lib/common.sh"

COUNT=8
PORT_BASE=8100
BINARY="$REPO_ROOT/build/bialet"
BIND_HOST="127.0.0.1"
FLAGS_STR="-x -w"
MANIFEST="$RUN_DIR/sites.tsv"
PIDS_FILE="$RUN_DIR/sites.pids"
RSS_DIR=""
DO_RSS=1
HZ=5
WAIT_SECONDS=60

usage() {
  print_usage_header "${BASH_SOURCE[0]}"
}

need_value() { (($# >= 2)) || die "$1 needs a value"; }

while (($#)); do
  case "$1" in
    -h|--help) usage; exit 0 ;;
    --count) need_value "$@"; COUNT="$2"; shift 2 ;;
    --count=*) COUNT="${1#*=}"; shift ;;
    --port-base) need_value "$@"; PORT_BASE="$2"; shift 2 ;;
    --port-base=*) PORT_BASE="${1#*=}"; shift ;;
    --apps-dir) need_value "$@"; APPS_DIR="$2"; shift 2 ;;
    --apps-dir=*) APPS_DIR="${1#*=}"; shift ;;
    --binary) need_value "$@"; BINARY="$2"; shift 2 ;;
    --binary=*) BINARY="${1#*=}"; shift ;;
    --bind-host) need_value "$@"; BIND_HOST="$2"; shift 2 ;;
    --bind-host=*) BIND_HOST="${1#*=}"; shift ;;
    --flags) need_value "$@"; FLAGS_STR="$2"; shift 2 ;;
    --flags=*) FLAGS_STR="${1#*=}"; shift ;;
    --log-dir) need_value "$@"; LOG_DIR="$2"; shift 2 ;;
    --log-dir=*) LOG_DIR="${1#*=}"; shift ;;
    --manifest) need_value "$@"; MANIFEST="$2"; shift 2 ;;
    --manifest=*) MANIFEST="${1#*=}"; shift ;;
    --pids-file) need_value "$@"; PIDS_FILE="$2"; shift 2 ;;
    --pids-file=*) PIDS_FILE="${1#*=}"; shift ;;
    --results) need_value "$@"; RSS_DIR="$2"; shift 2 ;;
    --results=*) RSS_DIR="${1#*=}"; shift ;;
    --no-rss) DO_RSS=0; shift ;;
    --hz) need_value "$@"; HZ="$2"; shift 2 ;;
    --hz=*) HZ="${1#*=}"; shift ;;
    --wait) need_value "$@"; WAIT_SECONDS="$2"; shift 2 ;;
    --wait=*) WAIT_SECONDS="${1#*=}"; shift ;;
    *) die "unknown option: $1 (try --help)" ;;
  esac
done

is_uint "$COUNT" && ((COUNT >= 1)) || die "--count must be at least 1"
is_uint "$PORT_BASE" && ((PORT_BASE >= 1 && PORT_BASE + COUNT - 1 <= 65535)) \
  || die "--port-base and --count exceed the port range"
is_uint "$HZ" && ((HZ >= 1 && HZ <= 100)) || die "--hz must be 1-100"
is_uint "$WAIT_SECONDS" || die "--wait must be seconds"
[[ -x "$BINARY" ]] || die "server binary not found: $BINARY (run make)"
BINARY="$(abs_path "$(dirname -- "$BINARY")")/$(basename -- "$BINARY")"
is_linux || die "this harness targets Linux"

read -r -a FLAGS <<<"$FLAGS_STR" || FLAGS=()
if ((${#FLAGS[@]} == 0)); then
  FLAGS=()
fi

ensure_dir "$RUN_DIR"
ensure_dir "$LOG_DIR"
ensure_dir "$(dirname -- "$MANIFEST")"
ensure_dir "$(dirname -- "$PIDS_FILE")"
CHECK_HOST="$BIND_HOST"
if [[ "$CHECK_HOST" == "0.0.0.0" || "$CHECK_HOST" == "::" || -z "$CHECK_HOST" ]]; then
  CHECK_HOST="127.0.0.1"
fi
if [[ -z "$RSS_DIR" ]]; then
  RSS_DIR="$RESULTS_DIR/$(utc_stamp)/mem"
fi
if ((DO_RSS == 1)); then
  ensure_dir "$RSS_DIR"
fi

# Refuse to clobber a live manifest: two supervisors on one port would make
# every number in the run meaningless.
if [[ -s "$MANIFEST" ]]; then
  manifest_alive=0
  while read -r pid; do
    if kill -0 "$pid" 2>/dev/null; then
      manifest_alive=1
      break
    fi
  done < <(awk -F'\t' 'NR > 1 && $4 ~ /^[0-9]+$/ { print $4 }' "$MANIFEST")
  if ((manifest_alive == 1)); then
    die "$MANIFEST still has live servers; run stop-sites.sh first"
  fi
  warn "removing stale manifest $MANIFEST"
  rm -f -- "$MANIFEST" "$PIDS_FILE"
fi

for ((i = 0; i < COUNT; i++)); do
  port=$((PORT_BASE + i))
  if port_open "$CHECK_HOST" "$port"; then
    die "port $port is already in use (stop the old servers or pick --port-base)"
  fi
done

STARTED_OK=0
SAMPLER_PID=""
SUP_PIDS=()
CHILD_PIDS=()
cleanup_on_error() {
  local rc=$?
  trap - EXIT INT TERM
  if ((STARTED_OK == 0)); then
    printf 'startup failed; stopping %s server(s)\n' "${#SUP_PIDS[@]}" >&2
    for pid in "${SUP_PIDS[@]:-}"; do
      [[ -n "$pid" ]] && stop_pid "$pid" 5
    done
    [[ -n "$SAMPLER_PID" ]] && stop_pid "$SAMPLER_PID" 5
    rm -f -- "$MANIFEST" "$PIDS_FILE" "$RUN_DIR/sites-sampler.pid"
  fi
  exit "$rc"
}
trap cleanup_on_error EXIT INT TERM

: >"$PIDS_FILE"
rm -f -- "$RUN_DIR/sites-sampler.pid"
{
  printf '# site\tport\tapp\tsupervisor_pid\tchild_pid\tlog\n'
} >"$MANIFEST"

for ((i = 1; i <= COUNT; i++)); do
  app="$APPS_DIR/site-$i"
  if [[ ! -f "$app/index.wren" ]]; then
    die "missing $app (run bench/gen-sites.sh --count $COUNT)"
  fi
  port=$((PORT_BASE + i - 1))
  log="$LOG_DIR/site-$i.log"
  printf '\n===== %s %s port %s =====\n' "$(date -u +%FT%TZ)" "$app" "$port" >>"$log"

  server_cmd=("$BINARY" -q -h "$BIND_HOST" -p "$port")
  if ((${#FLAGS[@]} > 0)); then
    server_cmd+=("${FLAGS[@]}")
  fi
  server_cmd+=("$app")
  (
    cd -- "$app"
    exec "${server_cmd[@]}"
  ) >>"$log" 2>&1 &
  supervisor=$!
  SUP_PIDS+=("$supervisor")

  if ! wait_for_port "$CHECK_HOST" "$port" "$WAIT_SECONDS" "$supervisor"; then
    printf 'server for %s did not open port %s; log tail:\n' "$app" "$port" >&2
    tail -n 30 "$log" >&2 || true
    exit 1
  fi
  child="$(wait_for_child_pid "$supervisor" 10 || true)"
  if [[ -z "$child" ]]; then
    printf 'could not find the HTTP child of supervisor %s; log tail:\n' "$supervisor" >&2
    tail -n 30 "$log" >&2 || true
    exit 1
  fi
  CHILD_PIDS+=("$child")
  printf 'site-%s\t%s\t%s\t%s\t%s\t%s\n' \
    "$i" "$port" "$app" "$supervisor" "$child" "$log" >>"$MANIFEST"
  printf 'site-%s %s\n' "$i" "$child" >>"$PIDS_FILE"
  info "site-$i: http://$BIND_HOST:$port (supervisor $supervisor, http child $child)"
done

if ((DO_RSS == 1)); then
  rss_csv="$RSS_DIR/sites-rss.csv"
  bash "$BENCH_DIR/mem.sh" --pids-file "$PIDS_FILE" --out "$rss_csv" \
    --hz "$HZ" --duration 0 --phase sites \
    >"$RSS_DIR/sites-rss.log" 2>&1 &
  SAMPLER_PID=$!
  printf '%s\n' "$SAMPLER_PID" >"$RUN_DIR/sites-sampler.pid"
  info "RSS sampler: $rss_csv (pid $SAMPLER_PID)"
fi

STARTED_OK=1
trap - EXIT INT TERM
printf '\nmanifest: %s\n' "$MANIFEST"
printf 'logs:     %s\n' "$LOG_DIR"
printf 'stop with: %s/stop-sites.sh\n' "$BENCH_DIR"
